function validate([points]) {
  if (points.length < 1 || points.length > 10) return 'points needs 1 to 10 points.';
  const seen = new Set();
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    const [x, y] = point;
    if (x < 0 || x > 100 || y < 0 || y > 100) return 'Coordinates are between 0 and 100.';
    if (seen.has(x + ',' + y)) return 'The points must be distinct.';
    seen.add(x + ',' + y);
  }
  return null;
}

