function maxRectangleArea(points) {
  const key = (x, y) => x + ',' + y;
  const seen = new Set(points.map(([x, y]) => key(x, y)));
  let best = -1;

  for (const [x1, y1] of points) {
    for (const [x2, y2] of points) {
      if (x1 >= x2 || y1 >= y2) {
        continue;
      }
      if (!seen.has(key(x1, y2)) || !seen.has(key(x2, y1))) {
        continue;
      }
      let inside = 0;
      for (const [x, y] of points) {
        if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
          inside++;
        }
      }
      if (inside === 4) {
        best = Math.max(best, (x2 - x1) * (y2 - y1));
      }
    }
  }
  return best;
}

