function maxRectangleArea(points) {
  // Try every group of four points: with distinct points, it is an axis-parallel rectangle
  // exactly when it uses two x values and two y values.
  const n = points.length;
  let best = -1;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        for (let d = c + 1; d < n; d++) {
          const corners = [points[a], points[b], points[c], points[d]];
          const xs = [...new Set(corners.map(p => p[0]))].sort((p, q) => p - q);
          const ys = [...new Set(corners.map(p => p[1]))].sort((p, q) => p - q);
          if (xs.length !== 2 || ys.length !== 2) continue;
          const others = points.filter((p, i) => i !== a && i !== b && i !== c && i !== d);
          const blocked = others.some(([x, y]) => x >= xs[0] && x <= xs[1] && y >= ys[0] && y <= ys[1]);
          if (!blocked) best = Math.max(best, (xs[1] - xs[0]) * (ys[1] - ys[0]));
        }
  return best;
}

