function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 10 : int(1, 10);
  const span = size === 'large' ? 100 : int(2, 6);
  // Most coordinates come from a few shared x and y values, so rectangles (and blocked ones) are common.
  const xs = Array.from({ length: int(2, 4) }, () => int(0, span));
  const ys = Array.from({ length: int(2, 4) }, () => int(0, span));
  const seen = new Set();
  const points = [];
  for (let tries = 0; points.length < n && tries < 1000; tries++) {
    const x = rand() < 0.85 ? xs[int(0, xs.length - 1)] : int(0, span);
    const y = rand() < 0.85 ? ys[int(0, ys.length - 1)] : int(0, span);
    if (seen.has(x + ',' + y)) continue;
    seen.add(x + ',' + y);
    points.push([x, y]);
  }
  return [points];
}
